pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address claimer, address receiver, uint256 amount) public {
        // Bound amount to avoid overflow issues
        vm.assume(amount <= 1e30);

        // Ensure the inputs are reasonable: receiver cannot be zero (otherwise claim reverts)
        vm.assume(receiver != address(0));

        // First, prepare state: renounce ownership so that owner() returns address(0)
        c.renounceOwnership();

        // Now attempt to claim - it will revert if amount > 0 because there are no shares
        // We expect the call to revert for any non-zero amount (since no deposits were made)
        // But we are testing the invariant: after renounce, owner() should return address(0)
        // and the contract should still function (i.e., not be bricked)

        // Drive the claim function - it will revert due to insufficient shares
        // But we are not testing whether it reverts; we are testing that owner() returns 0
        address ownerAddr = c.owner();

        // The general rule: After renounceOwnership(), owner() returns address(0)
        assertTrue(ownerAddr == address(0), "owner should be zero after renounce");
    }
}

